#include <map>

class entity;

class entity_id
{
  unsigned int val;
public:
  bool operator<(const entity_id& e) const { return val < e.val; }
};

class singleton
{
protected:
  singleton() {}
  virtual ~singleton() {}
private:
  singleton(const singleton&);
  singleton& operator=(const singleton&);
};

class charstarwrap
{
public:
  char* str;
  charstarwrap(char* s) { str = s; }
  bool operator<(const charstarwrap& csw) const
  {
    return strcmp(str, csw.str) < 0;
  }
};

typedef map<entity_id, entity*, less<entity_id>, malloc_alloc> entity_map;
typedef map<charstarwrap, unsigned int, less<charstarwrap>, malloc_alloc> name_to_number_map;

class entity_manager : entity_map, public singleton
{
public:
  void purge();
private:
  name_to_number_map name_to_number;
  int number_server;
};

void entity_manager::purge()
{
  name_to_number_map::iterator mi;
  mi = name_to_number.begin();
  for(; mi != name_to_number.end(); ++mi )
  {
    delete[] (*mi).first.str;
  }
  erase( begin(), end() );
  name_to_number = name_to_number_map();
  number_server = 0;
